import { apiv2Base, apiv2ServerHeaders } from "@/services/apiv2";

export default function getTourPricing(tourIds: number[], currency: any) {

    const res = fetch(
        `${apiv2Base()}/b2c/prices/tour`,
        {
            method: "POST",
            headers: {
            ...apiv2ServerHeaders(),
            "Content-type": "application/json",
        },
            body: JSON.stringify({ "ssr": true, "ids": tourIds, "b2c": "yes", "activeCurrency": currency, "roomType": "trp", "pax": 3 }),
            cache: "no-store"
        }
    ).then((res) => res.json())
        // Yetkisiz/hata durumunda uç dizi yerine obje döndürebilir; çağıranların hepsi .map ettiği için her zaman diziye normalize et.
        .then((data) => (Array.isArray(data) ? data : []))
        // Ağ hatası (WebKit "Load failed": kullanıcı sayfadan ayrıldı / bağlantı koptu / uç anlık
        // erişilemez) ya da JSON parse hatasında reject etmek yerine boş diziye düş. Aksi halde
        // çağıranların `.then` zinciri çalışmaz → priceLoading sonsuza kadar takılır + unhandled
        // rejection Sentry'e gürültü olur. Her çağıran zaten boş dizi durumunu yönetiyor.
        .catch(() => []);

    return res;
}