// Loading placeholder mirroring ListingCard's layout.
// Built with Tailwind (tw- prefix) as part of the Bootstrap → Tailwind migration.
export default function ListingCardSkeleton() {
  return (
    <div className="tw-flex tw-h-full tw-flex-col tw-overflow-hidden tw-rounded-[18px] tw-border tw-border-solid tw-border-[#ebe7f0] tw-bg-white tw-animate-pulse">
      {/* Image */}
      <div className="tw-aspect-[3/2] tw-w-full tw-bg-[#eef0f3]" />

      {/* Body */}
      <div className="tw-flex tw-flex-1 tw-flex-col tw-gap-2 tw-p-[14px]">
        {/* Badges */}
        <div className="tw-flex tw-gap-1.5">
          <span className="tw-h-4 tw-w-20 tw-rounded-full tw-bg-[#eef0f3]" />
          <span className="tw-h-4 tw-w-14 tw-rounded-full tw-bg-[#eef0f3]" />
        </div>

        {/* Title (two lines) */}
        <div className="tw-mt-1 tw-flex tw-flex-col tw-gap-1.5">
          <span className="tw-h-3.5 tw-w-full tw-rounded tw-bg-[#eef0f3]" />
          <span className="tw-h-3.5 tw-w-3/5 tw-rounded tw-bg-[#eef0f3]" />
        </div>

        {/* Meta */}
        <div className="tw-flex tw-gap-2.5">
          <span className="tw-h-3 tw-w-16 tw-rounded tw-bg-[#eef0f3]" />
          <span className="tw-h-3 tw-w-20 tw-rounded tw-bg-[#eef0f3]" />
        </div>

        {/* Rating */}
        <span className="tw-h-3 tw-w-24 tw-rounded tw-bg-[#eef0f3]" />

        {/* Footer: price + CTA */}
        <div className="tw-mt-auto tw-flex tw-items-center tw-justify-between tw-pt-2">
          <span className="tw-h-3.5 tw-w-28 tw-rounded tw-bg-[#eef0f3]" />
          <span className="tw-h-8 tw-w-24 tw-rounded-full tw-bg-[#eef0f3]" />
        </div>
      </div>
    </div>
  );
}
